import React, { useMemo, useState, useEffect, useRef } from 'react';

/**
 * TableView - improved, interactive table component
 * Props:
 *  - rows: array of objects (required)
 *  - initialRowsPerPage: number (optional, default 10)
 *  - compact: boolean to reduce padding (optional)
 *
 * Features:
 *  - client-side search (global)
 *  - sortable columns (click header to toggle asc/desc)
 *  - column visibility toggles
 *  - pagination with page size selector
 *  - selectable rows with "select all" support
 *  - export CSV (visible columns + filtered rows)
 *  - sticky header and responsive scrolling
 */

export default function TableView({ rows = [], initialRowsPerPage = 10, compact = false }) {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState({ key: null, dir: null }); // dir: 'asc' | 'desc' | null
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(initialRowsPerPage);
  const [visibleCols, setVisibleCols] = useState(null); // null = all visible
  const [selected, setSelected] = useState(new Set());
  const containerRef = useRef(null);

  useEffect(() => {
    // Reset selections / paging when rows change
    setPage(0);
    setSelected(new Set());
    setVisibleCols(null);
  }, [rows]);

  if (!rows || rows.length === 0) {
    return <div className="text-muted small">No matching rows. Try a different area or upload data.</div>;
  }

  // attach original index to each row to keep stable identity
  const augmented = useMemo(() => rows.map((r, i) => ({ __idx: i, ...r })), [rows]);

  const allCols = useMemo(() => {
    // take union of keys using first row as canonical order
    const first = augmented[0] || {};
    return Object.keys(first).filter(k => k !== '__idx');
  }, [augmented]);

  useEffect(() => {
    if (visibleCols === null) {
      // initialize all visible
      const obj = {};
      allCols.forEach(c => (obj[c] = true));
      setVisibleCols(obj);
    }
  }, [allCols, visibleCols]);

  const toggleCol = (col) => {
    setVisibleCols(prev => ({ ...prev, [col]: !prev[col] }));
  };

  const visibleColumnList = useMemo(() => {
    if (!visibleCols) return allCols;
    return allCols.filter(c => visibleCols[c]);
  }, [allCols, visibleCols]);

  // filtering
  const filtered = useMemo(() => {
    if (!query) return augmented;
    const q = query.toLowerCase();
    return augmented.filter(row =>
      visibleColumnList.some(col => String(row[col] ?? '').toLowerCase().includes(q))
    );
  }, [augmented, query, visibleColumnList]);

  // sorting
  const sorted = useMemo(() => {
    if (!sortBy.key) return filtered;
    const key = sortBy.key;
    const dir = sortBy.dir === 'desc' ? -1 : 1;
    const copy = [...filtered];
    copy.sort((a, b) => {
      const va = a[key];
      const vb = b[key];
      // numbers first
      const na = parseFloat(va);
      const nb = parseFloat(vb);
      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * dir;
      // try dates
      const da = Date.parse(String(va));
      const db = Date.parse(String(vb));
      if (!isNaN(da) && !isNaN(db)) return (da - db) * dir;
      // fallback string compare
      return String(va ?? '').localeCompare(String(vb ?? '')) * dir;
    });
    return copy;
  }, [filtered, sortBy]);

  // pagination
  const pageCount = Math.max(1, Math.ceil(sorted.length / rowsPerPage));
  useEffect(() => {
    if (page >= pageCount) setPage(Math.max(0, pageCount - 1));
  }, [pageCount]);

  const pageRows = useMemo(() => {
    const start = page * rowsPerPage;
    return sorted.slice(start, start + rowsPerPage);
  }, [sorted, page, rowsPerPage]);

  const toggleSelect = (idx) => {
    setSelected(prev => {
      const s = new Set(prev);
      if (s.has(idx)) s.delete(idx); else s.add(idx);
      return s;
    });
  };

  const selectAllOnPage = (checked) => {
    setSelected(prev => {
      const s = new Set(prev);
      pageRows.forEach(r => {
        if (checked) s.add(r.__idx); else s.delete(r.__idx);
      });
      return s;
    });
  };

  const allOnPageSelected = pageRows.every(r => selected.has(r.__idx)) && pageRows.length > 0;

  const exportCSV = () => {
    const cols = visibleColumnList;
    const rowsToExport = sorted; // export filtered+sorted full result
    const csvRows = [cols.join(',')];
    for (const r of rowsToExport) {
      const values = cols.map(c => {
        const v = r[c];
        if (v == null) return '';
        // escape quotes
        const s = String(v).replace(/"/g, '""');
        return `"${s}"`;
      });
      csvRows.push(values.join(','));
    }
    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `table-export-${new Date().toISOString().slice(0,19)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const onHeaderClick = (col) => {
    setSortBy(prev => {
      if (prev.key !== col) return { key: col, dir: 'asc' };
      if (prev.dir === 'asc') return { key: col, dir: 'desc' };
      return { key: null, dir: null };
    });
  };

  return (
    <div className="bg-white p-3 rounded-2xl shadow-sm">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <input
            placeholder="Search..."
            value={query}
            onChange={e => { setQuery(e.target.value); setPage(0); }}
            className="border rounded-md px-2 py-1 text-sm"
            style={{ minWidth: 200 }}
          />

          <div className="flex items-center gap-1">
            <button className="px-2 py-1 text-sm rounded border" onClick={() => { setQuery(''); setSortBy({ key: null, dir: null }); setPage(0); }}>
              Reset
            </button>
            <button className="px-2 py-1 text-sm rounded border" onClick={exportCSV}>
              Export CSV
            </button>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="text-sm">Columns:
          <div className="flex gap-1 flex-wrap max-w-[250px] overflow-auto p-1 border rounded bg-gray-50">
            {allCols.map(col => (
              <label key={col} className="inline-flex items-center gap-1 text-xs px-1 py-0.5 border rounded whitespace-nowrap">
                <input type="checkbox" checked={!!visibleCols?.[col]} onChange={() => toggleCol(col)} className="h-3 w-3" />
                <span>{col}</span>
              </label>
            ))}
          </div>
        </div>
          <div className="flex gap-1 flex-wrap">
            {allCols.map(col => (
              <label key={col} className="inline-flex items-center gap-1 text-sm px-2 py-1 border rounded">
                <input type="checkbox" checked={!!visibleCols?.[col]} onChange={() => toggleCol(col)} />
                <span className="ml-1">{col}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      <div ref={containerRef} style={{ maxHeight: 320, overflow: 'auto' }}>
        <table className={`w-full table-auto text-sm ${compact ? 'text-xs' : ''}`}>
          <thead>
            <tr className="border-b bg-gray-50 sticky top-0">
              <th className="p-2">
                <input type="checkbox" checked={allOnPageSelected} onChange={(e) => selectAllOnPage(e.target.checked)} />
              </th>
              {visibleColumnList.map(col => (
                <th key={col} className="p-2 text-left cursor-pointer select-none" onClick={() => onHeaderClick(col)}>
                  <div className="flex items-center gap-2">
                    <span>{col}</span>
                    <span className="text-xs text-slate-500">
                      {sortBy.key === col ? (sortBy.dir === 'asc' ? '▲' : '▼') : ''}
                    </span>
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {pageRows.map((r) => (
              <tr key={r.__idx} className="hover:bg-gray-50">
                <td className="p-2 align-top">
                  <input type="checkbox" checked={selected.has(r.__idx)} onChange={() => toggleSelect(r.__idx)} />
                </td>
                {visibleColumnList.map(col => (
                  <td key={col} className="p-2 align-top whitespace-nowrap">
                    {String(r[col] ?? '')}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="flex items-center justify-between mt-3">
        <div className="text-sm text-slate-600">Showing {sorted.length} result(s). Selected: {selected.size}</div>

        <div className="flex items-center gap-2">
          <label className="text-sm">Rows</label>
          <select value={rowsPerPage} onChange={(e) => { setRowsPerPage(Number(e.target.value)); setPage(0); }} className="border rounded px-2 py-1 text-sm">
            {[5,10,25,50,100].map(n => <option key={n} value={n}>{n}</option>)}
          </select>

          <button className="px-2 py-1 border rounded" onClick={() => setPage(p => Math.max(0, p-1))} disabled={page === 0}>Prev</button>
          <div className="px-2">{page + 1} / {pageCount}</div>
          <button className="px-2 py-1 border rounded" onClick={() => setPage(p => Math.min(pageCount - 1, p + 1))} disabled={page >= pageCount - 1}>Next</button>
        </div>
      </div>
    </div>
  );
}
